from pathlib import Path
import json, copy, shutil

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/"reports"
D=json.loads((OUT/"end_to_end_results.json").read_text(encoding="utf-8"))
T=r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>__TITLE__</title>
<style>body{font:15px "Segoe UI","Microsoft YaHei",sans-serif;background:#f3f5f8;color:#18212c;margin:20px}h1{margin:4px 0}.summary,.bar,.card{background:white;border:1px solid #d9dee7;border-radius:10px;padding:12px;margin:12px 0}.bar{display:flex;gap:14px;flex-wrap:wrap;position:sticky;top:0;z-index:4}.panels{display:grid;grid-template-columns:repeat(3,minmax(220px,1fr));gap:12px}.stage{position:relative;background:#eee}.stage img{display:block;width:100%;height:auto}.stage canvas{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}.pill{display:inline-block;background:#e7eef8;border-radius:12px;padding:3px 8px;margin:2px;font-size:.85em}.muted{color:#687487}.cand{border-top:1px solid #ddd;padding:8px 0}.scores{display:grid;grid-template-columns:repeat(4,1fr);gap:4px}.m{display:inline-block;background:#eef3f8;padding:6px;margin:3px;border-radius:5px}button{cursor:pointer}dialog{max-width:90vw}#zoomCanvas{max-width:85vw;max-height:75vh}@media(max-width:850px){.panels{grid-template-columns:1fr}.scores{grid-template-columns:repeat(2,1fr)}.bar{position:static}}</style>
<body><h1>__TITLE__</h1><p>__INTRO__</p><div class="summary" id="summary"></div>
<div class="bar"><label>搜索 <input id="q" placeholder="文件名"></label><label>筛选 <select id="f"><option>全部</option><option>新增鸟框</option><option>类别分歧</option><option>无框</option><option>退步</option><option>多鸟漏检</option><option>待复核</option><option>改善</option><option>同源回放</option></select></label><label><input id="xml" type="checkbox" checked>XML</label><label><input id="pp" type="checkbox" checked>PP框</label><label><input id="rf" type="checkbox" checked>RF框</label><span id="n"></span></div><div id="cards"></div>
<dialog id="dlg"><button onclick="dlg.close()">关闭</button><h3 id="zt"></h3><img id="zi" hidden><canvas id="zc"></canvas></dialog>
<script>const D=__DATA__,MODE="__MODE__",C={xml:"#168744",ppyoloe:"#1874b9",rfdetr:"#dc5424"};const $=s=>document.querySelector(s),E=s=>String(s??"").replace(/[&<>"']/g,x=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[x]));
function draw(cv,im,arr,col,pre){if(!im.naturalWidth)return;cv.width=im.naturalWidth;cv.height=im.naturalHeight;let c=cv.getContext("2d");c.clearRect(0,0,cv.width,cv.height);for(let p of arr||[]){let b=p.bbox_xyxy||p,x=b[0],y=b[1],w=b[2]-x,h=b[3]-y;c.strokeStyle=col;c.lineWidth=Math.max(2,cv.width/500);c.strokeRect(x,y,w,h);if(p.class_name){let s=(pre||"")+" "+p.class_name+" d"+Number(p.detector_score).toFixed(2)+" c"+Number(p.classifier_top_score).toFixed(2);c.font=Math.max(12,cv.width/75)+"px sans-serif";let tw=c.measureText(s).width,hh=Math.max(18,cv.width/55);c.fillStyle=col;c.fillRect(x,y-hh,tw+8,hh);c.fillStyle="white";c.fillText(s,x+4,y-4)}}}
function scores(p){return Object.entries(p.classifier_scores||{}).map(x=>"<span>"+E(x[0])+": "+Number(x[1]).toFixed(4)+"</span>").join("")}
function zoom(src,b,title){let im=$("#zi"),cv=$("#zc");$("#zt").textContent=title;im.onload=()=>{let px=(b[2]-b[0])*.35,py=(b[3]-b[1])*.35,x=Math.max(0,b[0]-px),y=Math.max(0,b[1]-py),w=Math.min(im.naturalWidth-x,b[2]-b[0]+2*px),h=Math.min(im.naturalHeight-y,b[3]-b[1]+2*py);cv.width=1000;cv.height=Math.max(280,Math.round(1000*h/w));let c=cv.getContext("2d");c.drawImage(im,x,y,w,h,0,0,cv.width,cv.height);c.strokeStyle="red";c.lineWidth=4;c.strokeRect((b[0]-x)*cv.width/w,(b[1]-y)*cv.height/h,(b[2]-b[0])*cv.width/w,(b[3]-b[1])*cv.height/h);$("#dlg").showModal()};im.src=src}
function boxDetails(row,model,title){return row.models[model].display_candidates.map((p,i)=>'<div class="cand"><b>'+E(p.class_name)+'</b>　检测分 '+Number(p.detector_score).toFixed(4)+'　分类top分 '+Number(p.classifier_top_score).toFixed(4)+'　乘积排序值 '+Number(p.final_score_product??p.detector_score*p.classifier_top_score).toFixed(4)+'<br>框 '+E(JSON.stringify(p.bbox_xyxy))+(p.user_detection_review?'<br><b>'+E(p.user_detection_review.status)+'：'+E(p.user_detection_review.review_note)+'</b>':'')+' <button onclick=\'zoom('+JSON.stringify(row.asset)+','+JSON.stringify(p.bbox_xyxy)+','+JSON.stringify(row.filename+" · "+title)+')\'>局部放大</button><details><summary>八类得分</summary><div class="scores">'+scores(p)+'</div></details></div>').join("")}
function card(r){let b=r.models.ppyoloe.display_candidates,a=r.models.rfdetr.display_candidates,h='<section class="card" data-file="'+E(r.filename)+'"><h2>'+E(r.filename)+(r.expected_category_posthoc?'<span class="muted">　目录事后预期：'+E(r.expected_category_posthoc)+'（非真值）</span>':'')+' '+(r.status_labels||[]).map(x=>'<span class="pill">'+E(x)+'</span>').join("")+(r.same_photo?'<span class="pill">同源回放</span>':'')+(r.related_scene?'<span class="pill">相关场景</span>':'')+'</h2><div class="panels">';
for(let [name,key] of [["原图","original"],["PP-YOLOE+＋BioCLIP 2","ppyoloe"],["RF-DETR＋BioCLIP 2","rfdetr"]])h+='<div><h3>'+name+' '+(key==="ppyoloe"?b.length:key==="rfdetr"?a.length:0)+'框</h3><div class="stage"><img src="'+E(r.asset)+'" data-k="'+key+'"><canvas></canvas></div></div>';
h+='</div><details><summary>真值、逐框类别分数及状态</summary>'+(MODE==="fixed"?'<p>XML真值：'+E(JSON.stringify((r.truth||[]).map(x=>({class_name:x.class_name,bbox_xyxy:x.bbox_xyxy}))))+'</p><p>端到端正确实例：基准 '+r.end_to_end_change.baseline_correct_instances+'；RF＋BioCLIP 2 '+r.end_to_end_change.rfdetr_correct_instances+'；退步：'+E(JSON.stringify(r.end_to_end_change.regressed_instances))+'</p><p>XML空间未匹配框/目标：基准 '+r.per_model_end_to_end_metrics.ppyoloe.unmatched_displayed_boxes+'/'+r.per_model_end_to_end_metrics.ppyoloe.unmatched_truths+'；RF '+r.per_model_end_to_end_metrics.rfdetr.unmatched_displayed_boxes+'/'+r.per_model_end_to_end_metrics.rfdetr.unmatched_truths+'（不自动等同背景误检或漏标，需对照图像复核）。</p><p>RF空间未匹配候选：'+E(JSON.stringify(r.per_model_end_to_end_metrics.rfdetr.unmatched_prediction_candidates))+'；RF空间未匹配XML实例：'+E(JSON.stringify(r.per_model_end_to_end_metrics.rfdetr.unmatched_truth_instances))+'</p>':'');
h+='<h3>PP-YOLOE+＋BioCLIP 2</h3>'+boxDetails(r,"ppyoloe","PP")+'<h3>RF-DETR＋BioCLIP 2</h3>'+boxDetails(r,"rfdetr","RF")+'</details></section>';return h}
function has(r,f){let t=r.status_labels||[];if(f==="全部")return true;if(f==="新增鸟框")return t.some(x=>x.includes("新增鸟框"));if(f==="类别分歧")return t.includes("类别分歧");if(f==="无框")return t.includes("无框")||!r.models.ppyoloe.display_candidates.length||!r.models.rfdetr.display_candidates.length;if(f==="退步")return t.some(x=>x.includes("退步"));if(f==="多鸟漏检")return t.includes("多鸟漏检");if(f==="待复核")return t.includes("待复核");if(f==="改善")return t.includes("改善");if(f==="同源回放")return !!r.same_photo;return true}
function render(){let q=$('#q').value.toLowerCase(),f=$('#f').value,rows=D.rows.filter(r=>r.filename.toLowerCase().includes(q)&&has(r,f));$('#n').textContent=rows.length+' / '+D.rows.length+' 张';$('#cards').innerHTML=rows.map(card).join('');for(let s of document.querySelectorAll('.card')){let r=D.rows.find(x=>x.filename===s.dataset.file);for(let [i,im] of [...s.querySelectorAll('img[data-k]')].entries()){im.onload=()=>{let cv=s.querySelectorAll('canvas')[i],k=im.dataset.k;if(k==='original')draw(cv,im,MODE==='fixed'&&$('#xml').checked?r.truth:[],C.xml,'XML');else if(k==='ppyoloe')draw(cv,im,$('#pp').checked?r.models.ppyoloe.display_candidates:[],C.ppyoloe,'P');else draw(cv,im,$('#rf').checked?r.models.rfdetr.display_candidates:[],C.rfdetr,'R')};if(im.complete)im.onload()}}}
function summary(){if(MODE==='fixed'){let s=D.summary,h='<h2>端到端固定验证指标（TP要求位置和类别都正确）</h2>';for(let m of ['ppyoloe','rfdetr']){let x=s[m];h+='<b>'+m+'</b> ';for(let [k,v] of [['TP',x.TP],['FP',x.FP],['FN',x.FN],['P',x.Precision.toFixed(4)],['R',x.Recall.toFixed(4)],['F1',x.F1.toFixed(4)],['无框图',x.images_with_no_boxes],['类别分歧图',x.class_disagreement_images]])h+='<span class="m">'+k+' '+v+'</span>'}h+='<p>逐类指标和混淆矩阵见CSV/JSON。检测AP不等于本页物种识别指标。</p>';$('#summary').innerHTML=h}else{let h='<h2>外来图框数（没有逐实例真值，不是准确率）</h2>';for(let [k,l] of [['all_80','全部80'],['exclude_9_same_source','排除9张同源回放'],['exclude_9_same_source_and_related_scene','再排除相关场景']]){let x=D.summary[k];h+='<h3>'+l+' ('+x.images+')</h3>';for(let m of ['ppyoloe','rfdetr']){let z=x.models[m];h+=m+'：'+z.images_with_any_box+'张有框 / '+z.displayed_boxes+'框；无框 '+z.no_box_images.length+'张<br>'}}$('#summary').innerHTML=h}}
summary();render();$('#q').oninput=render;$('#f').onchange=render;for(let x of ['xml','pp','rf'])$('#'+x).onchange=render;</script></body></html>'''

def save(name,title,rows,mode,intro):
    page_rows=copy.deepcopy(rows)
    for i,row in enumerate(page_rows):
        if mode=="external":
            source=ROOT/"assets"/"external80"/Path(row["asset"]).name
            dest=ROOT/"assets"/"external80"/(f"{i:03d}.jpg")
            if not dest.exists(): shutil.copy2(source,dest)
            row["asset"]="../assets/external80/"+dest.name
        else:
            row["asset"]="../"+row["asset"]
    data={"rows":page_rows,"summary":D["fixed_validation"]["summary"] if mode=="fixed" else D["external80"]["scopes"]}
    html=T.replace("__TITLE__",title).replace("__INTRO__",intro).replace("__MODE__",mode).replace("__DATA__",json.dumps(data,ensure_ascii=False,separators=(",",":")).replace("<","\\u003c"))
    (OUT/name).write_text(html,encoding="utf-8")

def main():
    fixed=D["fixed_validation"]["rows"];ext=D["external80"]["rows"]
    save("fixed_val_end_to_end.html","固定172张：PP-YOLOE+＋BioCLIP 2 vs RF-DETR＋BioCLIP 2",fixed,"fixed","同一真值版本；端到端TP要求IoU≥0.5一对一且物种类别正确。该验证集已反复探索，不是独立测试。")
    save("external80_end_to_end.html","外来80张：PP-YOLOE+＋BioCLIP 2 vs RF-DETR＋BioCLIP 2",ext,"external","外来图无逐实例真值；目录名称只作事后预期，不计算准确率/mAP。")
    index='''<!doctype html><meta charset="utf-8"><h1>RF-DETR＋BioCLIP 2端到端对照</h1><p>检测分数和分类分数独立展示。</p><ul><li><a href="fixed_val_end_to_end.html">固定验证集172张逐图对照</a></li><li><a href="external80_end_to_end.html">外来80张逐图对照与人工确认</a></li><li><a href="实验说明与结论.md">实验说明与结论</a></li><li><a href="../README.md">运行与复现说明</a></li><li><a href="end_to_end_results.json">完整结果JSON</a></li><li><a href="fixed_val_per_class.csv">逐类指标</a></li><li><a href="fixed_val_per_image.csv">逐图指标</a></li><li><a href="fixed_val_confusion_matrix.csv">混淆矩阵</a></li><li><a href="fixed_val_per_box.csv">固定验证逐框与八类分数</a></li><li><a href="external80_per_box.csv">外来图逐框与八类分数</a></li><li><a href="manual_review_scope.json">确认与待复核清单</a></li></ul>'''
    (OUT/"index.html").write_text(index,encoding="utf-8")
    print(json.dumps({"fixed":len(fixed),"external":len(ext)},ensure_ascii=False))
if __name__=="__main__":main()
